Looking at this task, I need to create a Python script that loads Eurostat data into normalized long format. Let me first examine the input files to understand their structure.

<solution_file path="src/t02_load_eurostat.py">
import csv
import json
import os
import sys

def read_csv_file(filepath):
    """Read a CSV file and return list of dictionaries."""
    rows = []
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows

def read_json_file(filepath):
    """Read a JSON file and return parsed data."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def main():
    # Determine base directory (script location or current directory)
    script_dir = os.path.dirname(os.path.abspath(__file__))
    base_dir = os.path.dirname(script_dir)

    # Input file paths
    selected_indicators_path = os.path.join(base_dir, 'outputs', 't01_selected_indicators.csv')
    api_config_path = os.path.join(base_dir, 'inputs', 'eurostat', 'sample_api_config.json')
    eurostat_data_path = os.path.join(base_dir, 'inputs', 'eurostat', 'eurostat_city_values_sample.csv')

    # Output file path
    output_path = os.path.join(base_dir, 'outputs', 't02_eurostat_raw.csv')

    # Read selected indicators
    selected_indicators = read_csv_file(selected_indicators_path)

    # Build a set of selected indicator IDs and a lookup for indicator names
    selected_indicator_ids = set()
    indicator_name_map = {}

    for ind in selected_indicators:
        # Handle various possible column names for indicator ID
        indicator_id = None
        indicator_name = None

        # Try common column names
        for key in ind:
            key_lower = key.lower().strip()
            if 'indicator' in key_lower and 'id' in key_lower:
                indicator_id = ind[key].strip()
            elif 'indicator' in key_lower and 'name' in key_lower:
                indicator_name = ind[key].strip()

        # If we couldn't find with the above logic, try first two columns
        if indicator_id is None or indicator_name is None:
            keys = list(ind.keys())
            if len(keys) >= 2:
                if indicator_id is None:
                    indicator_id = ind[keys[0]].strip()
                if indicator_name is None:
                    indicator_name = ind[keys[1]].strip()

        if indicator_id:
            selected_indicator_ids.add(indicator_id)
            if indicator_name:
                indicator_name_map[indicator_id] = indicator_name

    print(f"Selected {len(selected_indicator_ids)} indicators")
    print(f"Selected indicator IDs: {selected_indicator_ids}")

    # Read Eurostat data
    eurostat_data = read_csv_file(eurostat_data_path)
    print(f"Read {len(eurostat_data)} rows from Eurostat data")

    # If the Eurostat data is in wide format (one row per city, columns for each indicator),
    # we need to reshape it to long format
    # Detect if data is in wide or long format
    if len(eurostat_data) > 0:
        first_row = eurostat_data[0]
        keys = list(first_row.keys())

        # Check if we have indicator-specific columns (wide format)
        # Wide format typically has columns like "indicator_1", "indicator_2", etc.
        # or columns matching indicator IDs
        is_wide_format = False
        indicator_columns = []

        for key in keys:
            key_stripped = key.strip()
            # Check if any column name matches or contains a selected indicator ID
            for sel_id in selected_indicator_ids:
                if sel_id in key_stripped or key_stripped == sel_id:
                    is_wide_format = True
                    indicator_columns.append(key_stripped)
                    break
            # Also check for common wide format patterns
            if not is_wide_format:
                for part in key_stripped.split():
                    if part in selected_indicator_ids:
                        is_wide_format = True
                        if key_stripped not in indicator_columns:
                            indicator_columns.append(key_stripped)
                        break

    # Process the data into normalized long format
    output_rows = []
    seen_keys = set()  # Track (city_id, year, indicator_id) to avoid duplicates

    for row in eurostat_data:
        # Extract city_id and city_name
        city_id = None
        city_name = None
        year = None

        for key in row:
            key_lower = key.lower().strip()
            key_stripped = key.strip()

            if 'city' in key_lower and 'id' in key_lower:
                city_id = row[key].strip()
            elif 'city' in key_lower and 'name' in key_lower:
                city_name = row[key].strip()
            elif 'city' in key_lower and city_id is None:
                city_name = row[key].strip()
            elif key_lower in ('year', 'yr', 'y'):
                year = row[key].strip()

        # If we couldn't find city_id with the above, try common patterns
        if city_id is None:
            for key in row:
                key_lower = key.lower().strip()
                if 'id' in key_lower and city_name is None and 'city' not in key_lower:
                    city_id = row[key].strip()
                    break

        if city_name is None:
            for key in row:
                key_lower = key.lower().strip()
                if 'city' in key_lower:
                    city_name = row[key].strip()
                    break

        if city_id is None and len(row) > 0:
            keys = list(row.keys())
            city_id = row[keys[0]].strip()

        if city_name is None and len(row) > 1:
            keys = list(row.keys())
            city_name = row[keys[1]].strip()

        if year is None:
            for key in row:
                key_lower = key.lower().strip()
                if 'year' in key_lower or 'yr' in key_lower:
                    year = row[key].strip()
                    break

        if year is None and len(row) > 2:
            keys = list(row.keys())
            year = row[keys[2]].strip()

        if city_id is None or year is None:
            continue

        if is_wide_format:
            # Wide format: process indicator columns
            for ind_col in indicator_columns:
                indicator_id = None
                value = None

                # Try to extract indicator ID from column name
                for sel_id in selected_indicator_ids:
                    if sel_id in ind_col or ind_col == sel_id:
                        indicator_id = sel_id
                        break

                if indicator_id is None:
                    continue

                if indicator_id not in selected_indicator_ids:
                    continue

                value = row.get(ind_col, '').strip()

                if not value:
                    continue

                # Try to convert value to numeric
                numeric_value = None
                try:
                    numeric_value = float(value.replace(',', '').replace('"', '').strip())
                except (ValueError, AttributeError):
                    numeric_value = value

                # Create unique key to avoid duplicates
                unique_key = (city_id, year, indicator_id)
                if unique_key in seen_keys:
                    continue
                seen_keys.add(unique_key)

                indicator_name = indicator_name_map.get(indicator_id, indicator_id)

                output_rows.append({
                    'city_id': city_id,
                    'city_name': city_name,
                    'year': year,
                    'indicator_id': indicator_id,
                    'indicator_name': indicator_name,
                    'value': numeric_value if numeric_value is not None else value,
                    'unit': ''
                })
        else:
            # Long format: each row already has indicator_id and value
            indicator_id = None
            value = None
            unit = None

            for key in row:
                key_lower = key.lower().strip()
                key_stripped = key.strip()

                if 'indicator' in key_lower and 'id' in key_lower:
                    indicator_id = row[key].strip()
                elif 'indicator' in key_lower and 'name' in key_lower:
                    pass  # We'll use the map
                elif key_lower == 'value' or key_lower == 'val':
                    value = row[key].strip()
                elif key_lower == 'unit' or key_lower == 'units':
                    unit = row[key].strip()

            # Fallback for column detection
            if indicator_id is None:
                for key in row:
                    key_lower = key.lower().strip()
                    if 'indicator' in key_lower:
                        indicator_id = row[key].strip()
                        break

            if value is None:
                for key in row:
                    key_lower = key.lower().strip()
                    if key_lower in ('value', 'val', 'v'):
                        value = row[key].strip()
                        break

            if unit is None:
                for key in row:
                    key_lower = key.lower().strip()
                    if key_lower in ('unit', 'units'):
                        unit = row[key].strip()
                        break

            if indicator_id is None or value is None:
                continue

            indicator_id = indicator_id.strip()

            if indicator_id not in selected_indicator_ids:
                continue

            # Create unique key to avoid duplicates
            unique_key = (city_id, year, indicator_id)
            if unique_key in seen_keys:
                continue
            seen_keys.add(unique_key)

            indicator_name = indicator_name_map.get(indicator_id, indicator_id)

            output_rows.append({
                'city_id': city_id,
                'city_name': city_name,
                'year': year,
                'indicator_id': indicator_id,
                'indicator_name': indicator_name,
                'value': value,
                'unit': unit if unit else ''
            })

    # Sort output for consistency
    output_rows.sort(key=lambda x: (x['city_id'], x['year'], x['indicator_id']))

    print(f"Writing {len(output_rows)} rows to output")

    # Write output CSV
    fieldnames = ['city_id', 'city_name', 'year', 'indicator_id', 'indicator_name', 'value', 'unit']

    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, quoting=csv.QUOTE_MINIMAL)
        writer.writeheader()
        for row in output_rows:
            writer.writerow(row)

    print(f"Output written to {output_path}")

if __name__ == '__main__':
    main()
